using System.Security.Cryptography;
using System.Text.Json;
using UnscRelay.Core;
internal static class LocalErasureJournalChecks
{
 public static int Run(){var root=Directory.CreateTempSubdirectory("relay-local-erasure-journal-");var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS local erasure journal: "+label);}try{using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);var publicKey=key.ExportSubjectPublicKeyInfo();var keyId=Convert.ToHexString(SHA256.HashData(publicKey))[..32];var verifier=new ErasureReceiptVerifier(new Dictionary<string,string>{{keyId,Convert.ToBase64String(publicKey)}});var owner=new string('A',64);const string subject="61616161-6161-4161-8161-616161616161";var now=DateTimeOffset.UtcNow;var claims=new ErasureReceiptClaims(1,"https://unsc.responda.eu","unsc-relay-desktop-erasure",owner,subject,Guid.NewGuid(),now.AddDays(-31).ToUnixTimeMilliseconds(),now.AddDays(-1).ToUnixTimeMilliseconds(),"completed",now.ToUnixTimeMilliseconds());var bytes=JsonSerializer.SerializeToUtf8Bytes(claims,VaultSyncCrypto.Json);string Encode(byte[] value)=>Convert.ToBase64String(value).TrimEnd('=').Replace('+','-').Replace('/','_');var receipt=new ErasureReceipt(keyId,Encode(bytes),Encode(key.SignData(bytes,HashAlgorithmName.SHA256,DSASignatureFormat.IeeeP1363FixedFieldConcatenation)));var store=new AccountSyncStore(root.FullName);store.Save(new(){Owner=owner,Subject=subject,Activated=true});File.WriteAllText(Path.Combine(root.FullName,"keys.vault"),"encrypted fixture sentinel");var spaces=new AccountWorkspaces(root.FullName);spaces.Remember(store.Load());var journal=new LocalErasureJournal(root.FullName,verifier);
 try{journal.Accept(receipt with{Signature=Encode(new byte[64])},owner,subject,claims.RequestId,Guid.Empty);throw new Exception("Forged receipt persisted");}catch(InvalidDataException){Check(!Directory.Exists(Path.Combine(root.FullName,"ErasureJournal")),"invalid receipt creates no local destruction state");}
 journal.Accept(receipt,owner,subject,claims.RequestId,Guid.Empty);var file=Path.Combine(root.FullName,"ErasureJournal",owner+".dpapi");Check(File.Exists(file)&&!System.Text.Encoding.UTF8.GetString(File.ReadAllBytes(file)).Contains(subject,StringComparison.Ordinal),"permanent receipt is protected outside update and migration backups");Check(journal.Notices().Single().Workspaces.SequenceEqual(new[]{Guid.Empty}),"journal records the exact legacy workspace without treating the shared root as a recursive delete target");try{journal.GuardWorkspace(Guid.Empty);throw new Exception("Erased workspace opened");}catch(LocalAccountErasedException){Check(File.ReadAllText(Path.Combine(root.FullName,"keys.vault"))=="encrypted fixture sentinel","verified erasure blocks opening without modifying vault bytes");}
 var foreign=spaces.Add("foreign@example.invalid");var foreignPath=spaces.DirectoryFor(foreign);new AccountSyncStore(foreignPath).Save(new(){Owner=new string('B',64),Subject="62626262-6262-4262-8262-626262626262",Activated=true});spaces.Select(foreign);Check(journal.Accept(receipt,owner,subject,claims.RequestId,Guid.Empty).Owner==owner,"receipt binds its actual workspace even when the global account preference changes");journal.GuardWorkspace(foreign);Check(true,"another account remains eligible to open its own workspace");File.WriteAllText(Path.Combine(foreignPath,"keys.vault"),"foreign fixture");File.WriteAllText(Path.Combine(root.FullName,"keys.vault.before-windows-hello"),"pre-Hello encrypted fixture");File.WriteAllText(Path.Combine(root.FullName,"keys.vault.before-passkeys"),"pre-passkey encrypted fixture");File.WriteAllText(Path.Combine(root.FullName,"unrelated-user-file.txt"),"unrelated fixture");var updateBackup=UpdateBackup.Create(root.FullName,"fixture");var outside=Directory.CreateDirectory(Path.Combine(root.FullName,"outside-target"));File.WriteAllText(Path.Combine(outside.FullName,"sentinel.txt"),"outside fixture");Directory.CreateSymbolicLink(Path.Combine(root.FullName,"NativeHome"),outside.FullName);var plan=new LocalErasurePlanner(root.FullName,journal).Create(owner);Check(plan.Items.Any(item=>item.Relative=="keys.vault")&&plan.Items.Any(item=>item.Relative=="keys.vault.before-windows-hello")&&plan.Items.Any(item=>item.Relative=="keys.vault.before-passkeys"),"cleanup plan includes current, pre-Hello and legacy pre-passkey vaults");Check(!plan.Items.Any(item=>item.Relative.StartsWith("Accounts/"+foreign.ToString("N")+"/",StringComparison.Ordinal)),"cleanup plan excludes another account's live workspace");var backupRelative=Path.GetRelativePath(root.FullName,updateBackup).Replace('\\','/');Check(plan.Items.Any(item=>item.Relative==backupRelative+"/keys.vault")&&!plan.Items.Any(item=>item.Relative.StartsWith(backupRelative+"/Accounts/"+foreign.ToString("N")+"/",StringComparison.Ordinal)),"mixed update backup retains another account while selecting the erased owner's copies");Check(plan.Items.Any(item=>item.Relative=="NativeHome"&&item.Link)&&!plan.Items.Any(item=>item.Relative.Contains("sentinel.txt",StringComparison.Ordinal)),"local links are scheduled as link objects without reading their target tree");Check(!plan.Items.Any(item=>item.Relative=="unrelated-user-file.txt")&&File.ReadAllText(Path.Combine(foreignPath,"keys.vault"))=="foreign fixture","unmanaged root files and another owner's bytes remain untouched during planning");Check(plan.Bindings.Contains("account-sync.dpapi")&&plan.Bindings.Contains(backupRelative+"/account-sync.dpapi"),"identity and token bindings are explicitly scheduled last in live and backup scopes");var ambiguous=Path.Combine(root.FullName,"UpdateBackups","20260101-000000-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(ambiguous);File.WriteAllText(Path.Combine(ambiguous,"keys.vault"),"unknown owner's vault");var ambiguousIndex=new AccountWorkspaceIndex();ambiguousIndex.Accounts.Add(new(Guid.Empty,owner,"fixture@example.invalid","fixture"));new AccountWorkspaces(ambiguous).Save(ambiguousIndex);Check(!new LocalErasurePlanner(root.FullName,journal).Create(owner).Items.Any(item=>item.Relative.StartsWith(Path.GetRelativePath(root.FullName,ambiguous).Replace('\\','/')+"/",StringComparison.Ordinal)),"backup index alone never attributes an unbound legacy root to the erased owner");Directory.Delete(Path.Combine(root.FullName,"NativeHome"));var backup=SyncLocalBackup.Create(root.FullName,true);File.Delete(Path.Combine(root.FullName,"account-sync.dpapi"));try{journal.GuardWorkspace(Guid.Empty);throw new Exception("Restored identity opened");}catch(LocalAccountErasedException){Check(!File.Exists(Path.Combine(root.FullName,"account-sync.dpapi")),"journal rejects pending restoration before it can resurrect erased account metadata");}
 File.Delete(Path.Combine(root.FullName,"sync-transaction.json"));File.Delete(Path.Combine(root.FullName,"keys.vault"));File.WriteAllText(Path.Combine(root.FullName,"profiles.json"),"residual profile fixture");try{journal.GuardWorkspace(Guid.Empty);throw new Exception("Residual workspace opened without identity or vault");}catch(LocalAccountErasedException){Check(true,"unfinished erased workspace stays locked when only residual profiles remain");}
 Check(!UpdateBackup.DataFiles.Any(name=>name.Contains("ErasureJournal",StringComparison.Ordinal)),"update-backup allowlist excludes permanent erasure state");var held=File.ReadAllBytes(file);File.Delete(file);File.CreateSymbolicLink(file,Path.Combine(root.FullName,"missing-proof"));try{journal.GuardWorkspace(Guid.Empty);throw new Exception("Dangling proof link accepted");}catch(IOException){Check(true,"dangling journal links fail closed instead of pretending no receipt exists");}File.Delete(file);File.WriteAllBytes(file,held);var corrupted=File.ReadAllBytes(file);corrupted[corrupted.Length/2]^=1;File.WriteAllBytes(file,corrupted);try{journal.GuardWorkspace(Guid.Empty);throw new Exception("Corrupted journal accepted");}catch(Exception error)when(error is InvalidDataException or InvalidOperationException or CryptographicException){Check(true,"corrupted local proof never falls back to restoring a vault");}Console.WriteLine("Local erasure journal checks: "+count);return 0;}finally{root.Delete(true);}}
}
